settings.liquid:
{%- assign bundleandsave = false -%}

{%- if product.tags contains 'bundleandsave' -%}
  {%- assign bundleandsave = true -%}
{%- endif -%}

{% assign tagline = nil %}
{%- if product.metafields.accentuate.tagline -%}
  {%- assign tagline = product.metafields.accentuate.tagline -%}
{%- endif -%}

{%- if collection -%}
  {%- if collection.metafields.accentuate.tagline and collection.metafields.accentuate.collection_tagline_overwrite -%}
    {%- assign tagline = collection.metafields.accentuate.tagline -%}
  {%- endif -%}
{%- endif -%}

{% if tagline != blank %}
  {%- if hidden -%}
    {%- if tagline contains 'code:' or tagline contains 'CODE:' or tagline contains 'Code:' -%}
      <input type="hidden" value="{{ tagline | escape }}" name="properties[Promo]"/>
    {%- endif -%}
  {%- else -%}
    <!--Snippets: product-tagline:19-->
    <p class="cProductCard-tagline {% if bundleandsave %}cProductCard-tagline--large{% endif %}">{{ tagline }}</p>
  {%- endif -%}
{% endif %}

{% assign hideuk-PDPTAG4 = false %}
              {% if localization.country.iso_code == 'GB' %}
                {% for tag in product.tags %}
                  {% if tag == 'hideuk-PDPTAG4' %}
                    {% assign hideuk-PDPTAG4 = true %}
                    {% break %}
                  {% endif %}
                {% endfor %}
              {% endif %}
              {% unless hideuk-PDPTAG4 %}
          {% assign show_taglist = false %}
            {% for tag in product.tags %}
              {% if tag contains "PDPTAG4-" %}
                {% assign show_taglist = true %}
              {% endif %}
            {% endfor %}
            {% if show_taglist and request.page_type == "collection" or request.page_type == "product" and show_taglist %}
              <div class="tg4-taglist-main tag4">
              {% for tag in product.tags %}
                {% if tag contains "PDPTAG4-" %}
                  {% assign tag_parts = tag | split: "-" %}
                  {% assign hascode = tag_parts[1] %}
                  {% assign tag_label = tag_parts[2] %}
                  <div class="tg4-tag-custom" style="--tag4color:#{{ hascode }};">
                    {{ tag_label }}
                  </div>
                {% break %}
                {% endif %}
              {% endfor %}
              </div>
            {% endif %}
            {% endunless %}
